import {blocksFor} from '../core/sessions.js';
import {addDays,dateKey} from '../core/model.js';
import {imageStore} from './assets.js';
const $=s=>document.querySelector(s),tones={blue:'#dfefff',green:'#ddf2e7',orange:'#ffecd4',purple:'#ece2ff',rose:'#ffe4ec',slate:'#e6eef4'};
function round(ctx,x,y,w,h,r=16){ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,r);else{ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}ctx.fill();}
function lines(ctx,text,maxWidth,maxLines=3){const out=[];let line='';for(const c of text){if(ctx.measureText(line+c).width>maxWidth&&line){out.push(line);line='';if(out.length===maxLines){out[maxLines-1]=out[maxLines-1].slice(0,-1)+'…';return out;}}line+=c;}if(line)out.push(line);return out;}
export function setupPoster({get,notify,openSheet}){
 let generation=0,currentBlob=null;
 async function render(){const token=++generation;currentBlob=null;$('#poster-share').disabled=true;$('#poster-save').disabled=true;const {courses,settings,week,weekend}=get(),canvas=$('#poster-canvas'),ctx=canvas.getContext('2d'),style=$('#poster-style').value,showTeacher=$('#poster-teacher').checked,showLocation=$('#poster-location').checked,includePersonal=$('#poster-personal').checked,days=weekend?7:5,w=1080,row=156,top=260,left=92,gap=8,cw=(w-left-40)/days;
  canvas.width=w;canvas.height=top+12*row+90;ctx.fillStyle=style==='pixel'?'#152c33':'#edf4f6';ctx.fillRect(0,0,w,canvas.height);
  if(style==='wallpaper'){const wallpaper=await imageStore('get');if(wallpaper){const url=URL.createObjectURL(wallpaper);try{const image=new Image();image.src=url;await image.decode();if(token!==generation)return;const s=Math.max(w/image.width,canvas.height/image.height);ctx.drawImage(image,(w-image.width*s)/2,(canvas.height-image.height*s)/2,image.width*s,image.height*s);ctx.fillStyle='#ffffffd9';ctx.fillRect(20,top-100,w-40,canvas.height-top+70);}finally{URL.revokeObjectURL(url);}}}
  if(token!==generation)return;const ink=style==='pixel'?'#d4fca3':'#183d52',font=style==='pixel'?'monospace':'"Microsoft YaHei", sans-serif';ctx.fillStyle=ink;ctx.font='bold 48px '+font;ctx.fillText('我的一周 · 第 '+week+' 周',44,90);ctx.font='24px '+font;const start=addDays(settings.startDate,(week-1)*7);ctx.fillText(dateKey(start)+' — '+dateKey(addDays(start,6)),44,140);ctx.font='22px '+font;for(let day=0;day<days;day++){const date=addDays(start,day);ctx.fillText(['周一','周二','周三','周四','周五','周六','周日'][day],left+day*cw+12,215);ctx.fillText((date.getMonth()+1)+'/'+date.getDate(),left+day*cw+12,245);}
  for(let p=0;p<12;p++){ctx.fillStyle=ink;ctx.font='bold 24px '+font;ctx.fillText(String(p+1).padStart(2,'0'),28,top+p*row+34);ctx.font='16px '+font;ctx.fillText(settings.times[p].split('-')[0],16,top+p*row+62);ctx.strokeStyle=style==='pixel'?'#44685f':'#cddce3';ctx.beginPath();ctx.moveTo(left,top+p*row);ctx.lineTo(w-30,top+p*row);ctx.stroke();}
  const list=blocksFor(courses,week,null,settings.times).filter(c=>c.day<=days&&(includePersonal||!c.personal));for(const c of list){const peers=list.filter(p=>p.day===c.day&&p.start<=c.end&&p.end>=c.start),lane=peers.findIndex(p=>p.sessionKey===c.sessionKey),width=cw/peers.length-gap,x=left+(c.day-1)*cw+lane*cw/peers.length+4,y=top+(c.start-1)*row+6,height=(c.end-c.start+1)*row-12;
   ctx.fillStyle=style==='pixel'?'#284b45':tones[c.tone]||tones.blue;round(ctx,x,y,width,height,style==='pixel'?2:18);ctx.fillStyle=ink;ctx.font='bold 24px '+font;const fields=[showLocation?c.location:'',showTeacher?c.teacher:''].filter(Boolean),title=lines(ctx,c.name,width-16,Math.max(1,Math.min(3,Math.floor((height-34-fields.length*25)/30))));let at=y+34;for(const line of title){ctx.fillText(line,x+8,at);at+=30;}ctx.font='20px '+font;for(const text of fields){for(const line of lines(ctx,text,width-16,1)){if(at+24<y+height){ctx.fillText(line,x+8,at+10);at+=25;}}}
  }ctx.fillStyle=ink;ctx.font='20px '+font;ctx.fillText('课间 · 按自己的节奏生活',44,canvas.height-30);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(token!==generation)return;if(!blob)throw Error('图片生成失败');currentBlob=blob;$('#poster-share').disabled=false;$('#poster-save').disabled=false;
 }
 async function data(){if(!currentBlob)throw Error('请等待预览生成');return {blob:currentBlob,name:'课间-第'+get().week+'周.png'};}
 async function base64(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});}
 async function save(){const {blob,name}=await data();if(window.CourseCompass?.saveImage){window.CourseCompass.saveImage(name,await base64(blob));return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 $('#poster-save').onclick=()=>save().catch(e=>notify(e.message));
 $('#poster-share').onclick=async()=>{try{const {blob,name}=await data();if(window.CourseCompass?.shareImage){window.CourseCompass.shareImage(await base64(blob));return;}const file=new File([blob],name,{type:'image/png'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'我的一周'});}else {await save();notify('当前浏览器不支持直接分享，已改为保存图片');}}catch(e){if(e.name!=='AbortError')notify(e.message);}};
 for(const id of ['style','teacher','location','personal'])$('#poster-'+id).onchange=()=>render().catch(e=>notify(e.message));
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="poster"]')){openSheet('#poster-sheet');render().catch(e=>notify(e.message));}});
}
